<?php
session_start();if(!isset($_SESSION['student_id'])){header('Location: index.php');exit;}require 'Includes/dbcon.php';
$limit=10;$stmt=$con->prepare('SELECT id, question, option_a, option_b, option_c, option_d FROM questions ORDER BY RAND() LIMIT ?');$stmt->bind_param('i',$limit);$stmt->execute();$qs=$stmt->get_result();$questions=$qs->fetch_all(MYSQLI_ASSOC);$_SESSION['current_exam_ids']=array_map('intval',array_column($questions,'id'));$pageTitle='Examination in Progress | FountainTest';include 'Includes/header.php';?>
<div class="d-flex justify-content-between align-items-start gap-3 flex-wrap mb-3"><div><span class="eyebrow">Assessment room</span><h1 class="h2 mt-2">Computer-Based Test</h1><p class="muted">Work independently and review your selections before submitting.</p></div><div class="timer" id="examTimer" data-minutes="20" aria-live="polite">20:00</div></div>
<?php if(!$questions):?><div class="alert alert-warning">There are no questions available yet. Please contact your examination administrator.</div><?php else:?><div class="exam-top"><div class="d-flex justify-content-between gap-3 mb-2"><strong>Examination progress</strong><span class="muted" id="progressText">0 of <?=count($questions)?> answered</span></div><div class="progress"><div class="progress-bar" id="examProgress" role="progressbar" style="width:0%"></div></div><div class="small muted mt-2">Duration: 20 minutes · Questions: <?=count($questions)?> · Select one answer per question.</div></div>
<form id="examForm" method="post" action="submit.php"><input type="hidden" name="exam_token" value="<?=htmlspecialchars($_SESSION['exam_token']=bin2hex(random_bytes(24)))?>">
<?php foreach($questions as $i=>$q):?><section class="question-card"><div class="question-number">Question <?=($i+1)?> of <?=count($questions)?></div><p class="question-text"><?=nl2br(htmlspecialchars($q['question']))?></p><?php foreach(['A'=>'option_a','B'=>'option_b','C'=>'option_c','D'=>'option_d'] as $letter=>$field):if(trim((string)$q[$field])==='')continue;?><label class="answer-option"><input type="radio" name="answer[<?=$q['id']?>]" value="<?=$letter?>"><span><strong><?=$letter?>.</strong> <?=htmlspecialchars($q[$field])?></span></label><?php endforeach;?></section><?php endforeach;?>
<div class="card"><div class="d-flex flex-column flex-md-row justify-content-between align-items-md-center gap-3"><div><strong>Ready to submit?</strong><div class="muted small">Once submitted, your answers will be marked and recorded.</div></div><button class="btn btn-success" type="submit">Submit examination →</button></div></div></form><?php endif;?>
